import{_ as i,c as a,a0 as o,o as t}from"./chunks/framework.B6JXc2q-.js";const h=JSON.parse('{"title":"认证运行时恢复规范","description":"","frontmatter":{},"headers":[],"relativePath":"spec/auth/auth_runtime_recovery.md","filePath":"spec/auth/auth_runtime_recovery.md"}'),d={name:"spec/auth/auth_runtime_recovery.md"};function l(c,e,r,n,s,u){return t(),a("div",null,e[0]||(e[0]=[o(`<h1 id="认证运行时恢复规范" tabindex="-1">认证运行时恢复规范 <a class="header-anchor" href="#认证运行时恢复规范" aria-label="Permalink to &quot;认证运行时恢复规范&quot;">​</a></h1><blockquote><p>本规范是当前认证状态机主线，定义 persistent auth、short session、runtime 的边界、 atomic 恢复行为、公共状态和验收门禁；不绑定短期 commit。</p></blockquote><h2 id="_1-术语与事实来源" tabindex="-1">1. 术语与事实来源 <a class="header-anchor" href="#_1-术语与事实来源" aria-label="Permalink to &quot;1. 术语与事实来源&quot;">​</a></h2><h3 id="_1-1-三层状态" tabindex="-1">1.1 三层状态 <a class="header-anchor" href="#_1-1-三层状态" aria-label="Permalink to &quot;1.1 三层状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>内容</th><th>事实/用途</th></tr></thead><tbody><tr><td>persistent auth</td><td><strong>最小能力</strong>：<code>userId</code>、<code>passToken</code>、<code>deviceId</code>；其余为诊断/兼容字段</td><td>TokenStore/<code>conf/auth.json</code> 的持久事实；用于 serviceLogin 换取 short session</td></tr><tr><td>short session</td><td><code>serviceToken</code>、<code>yetAnotherServiceToken</code></td><td>短期业务会话；旧 token 存在不代表仍有效</td></tr><tr><td>runtime</td><td>account、Mina/MiIO service、session、cookie、signature、device_id</td><td>进程内、必须经过 verify 才能成为当前运行态</td></tr></tbody></table><p>当前 primary 观测值为 <code>miaccount_persistent_auth_exchange</code>：它表示 <code>passToken → serviceToken</code> exchange via <code>serviceLogin</code>，不是 <code>MiAccount.login</code>。</p><p><code>AUTH_ACCESS_TOKEN</code> / <code>AUTH_REFRESH_TOKEN</code> 仅是运行时覆盖，不是持久事实：</p><ul><li>不得写入 TokenStore 或磁盘。</li><li>scheduled refresh 检测到 env override 必须 skip。</li><li>manual reload 可使用覆盖凭据重绑/verify，但不得换票或写盘。</li></ul><h2 id="_2-统一-atomic-runtime-transition" tabindex="-1">2. 统一 atomic runtime transition <a class="header-anchor" href="#_2-统一-atomic-runtime-transition" aria-label="Permalink to &quot;2. 统一 atomic runtime transition&quot;">​</a></h2><p>所有生产 runtime 切换必须遵循：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>candidate auth/runtime</span></span>
<span class="line"><span>  -&gt; verify candidate</span></span>
<span class="line"><span>  -&gt; TokenStore.commit（需要持久化且无 env override）</span></span>
<span class="line"><span>  -&gt; 一次性同步 swap 全部 runtime 引用</span></span>
<span class="line"><span>  -&gt; generation += 1</span></span>
<span class="line"><span>  -&gt; 关闭旧 session</span></span></code></pre></div><p>全部引用包括：<code>device_id</code>、<code>login_account</code>、<code>mina_service</code>、<code>miio_service</code>、 <code>mi_session</code>、<code>cookie_jar</code>、<code>login_signature</code>。</p><p>约束：</p><ol><li>candidate 构造/verify 失败：旧 runtime、旧 token、<code>saveTime</code> 不变。</li><li><code>TokenStore.commit()</code> 失败：旧内存镜像和旧 runtime 不变。</li><li>新引用必须在任何 <code>await old_session.close()</code> 前全部可见。</li><li>close 被取消或挂起，不得留下新 session+旧 service 混合状态。</li><li>事务受 <code>_auth_transition_lock</code> 保护。</li><li><code>runtime generation</code> 只在 verified runtime 提交后递增。</li></ol><p><code>rebuild_short_session_from_persistent_auth()</code> 默认 <code>atomic=True</code>。<code>atomic=False</code> 仅为 明确 legacy 兼容路径；生产调用点不得使用默认 destructive fallback。</p><h2 id="_3-恢复入口规范" tabindex="-1">3. 恢复入口规范 <a class="header-anchor" href="#_3-恢复入口规范" aria-label="Permalink to &quot;3. 恢复入口规范&quot;">​</a></h2><h3 id="_3-1-probe-与-try-login" tabindex="-1">3.1 Probe 与 <code>_try_login</code> <a class="header-anchor" href="#_3-1-probe-与-try-login" aria-label="Permalink to &quot;3.1 Probe 与 \`_try_login\`&quot;">​</a></h3><p>runtime probe 失败时：</p><ol><li>进入 transition lock。</li><li>env override 存在：只调用 atomic runtime rebind/verify。</li><li>完整 persistent auth 存在：fast rebind 未成功后只调用 atomic persistent-auth rebuild。</li><li>无论旧 <code>serviceToken</code> 是否存在，都不能跳过 atomic rebuild。</li><li>atomic rebuild 失败不得进入无口令 <code>MiAccount.login</code>。</li><li>full login 只允许在明确具备该能力且不属于上述 atomic recovery 的场景。</li></ol><h3 id="_3-2-scheduled-refresh" tabindex="-1">3.2 Scheduled refresh <a class="header-anchor" href="#_3-2-scheduled-refresh" aria-label="Permalink to &quot;3.2 Scheduled refresh&quot;">​</a></h3><p>scheduled refresh 的触发条件：</p><ul><li>当前 state 为 <code>HEALTHY</code>。</li><li>有效 <code>expires_in</code> 时：<code>saveTime + expires_in</code> 的剩余比例低于配置阈值；阈值 <code>auth_refresh_threshold</code> 安全夹在 <code>0.01..0.99</code>，模式为 <code>ttl_ratio</code>。</li><li>没有有效 <code>expires_in</code> 时：持久 <code>saveTime</code> 的 elapsed 达到 <code>auth_refresh_interval_hours</code>；该配置安全下限为 <code>0.01</code> 小时，默认 <code>12</code> 小时， 模式为 <code>interval_fallback</code>，不再额外乘阈值。</li><li>refresh attempt cooldown 已到期；它只约束 attempt timestamp。</li></ul><p>两种模式都只使用持久 token <code>saveTime</code> 作为时间锚点。runtime probe 成功不得更新 TTL/interval 锚点或 <code>saveTime</code>。</p><p>执行规则：</p><ul><li>env override：记录 <code>scheduled_env_override_skip</code>，不网络换票、不 commit。</li><li>无 persistent capability：记录 capability skip。</li><li>正常路径：调用 <code>rebuild_short_session_from_persistent_auth(atomic=True)</code>。</li><li>失败不得把仍健康 runtime 降级。</li><li>失败或 skip 都占用独立 attempt cooldown。</li></ul><h3 id="_3-3-manual-reload" tabindex="-1">3.3 Manual reload <a class="header-anchor" href="#_3-3-manual-reload" aria-label="Permalink to &quot;3.3 Manual reload&quot;">​</a></h3><p>manual reload 必须：</p><ol><li>TokenStore 存在时先真实调用 <code>reload_from_disk()</code>。</li><li>env override 模式：读取磁盘后应用 env，构造 candidate、verify、swap；不调用 <code>_serviceLogin</code>、不调用 <code>MiAccount.login</code>、不写盘。</li><li>非 env 模式：调用 atomic persistent-auth rebuild。</li><li><code>token_store_reloaded=true</code> 只在真实 reload 已执行时允许返回。</li><li>verified success 清除 manual gate。</li><li><code>runtime_swap_attempted</code> 只有结果明确为尝试时才为 true；<code>None</code>、缺省、<code>skipped</code> 均为 false。</li></ol><h2 id="_4-错误分类与公共状态" tabindex="-1">4. 错误分类与公共状态 <a class="header-anchor" href="#_4-错误分类与公共状态" aria-label="Permalink to &quot;4. 错误分类与公共状态&quot;">​</a></h2><h3 id="_4-1-fatal-长期认证失败" tabindex="-1">4.1 Fatal 长期认证失败 <a class="header-anchor" href="#_4-1-fatal-长期认证失败" aria-label="Permalink to &quot;4.1 Fatal 长期认证失败&quot;">​</a></h3><p>以下证据才允许设置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>long_term_expired = true</span></span>
<span class="line"><span>need_qr_scan = true</span></span>
<span class="line"><span>user_action_required = true</span></span></code></pre></div><ul><li>明确的 refresh/passport/service token expired</li><li>必要认证字段结构缺失</li></ul><p>need/scan QR、account locked、login required 只证明需要人工介入或交互挑战， 只映射 <code>need_qr_scan/user_action_required</code> 与对应 <code>auth_class</code>，不得设置 <code>long_term_expired</code>。</p><p><code>70016</code> 分类为 <code>credential_session_rejected</code>，<code>87001</code> 或 <code>captchaUrl</code> 分类为 <code>interactive_captcha_challenge</code>；这两类不得设置 <code>long_term_expired</code>，但无头恢复可设置 <code>need_qr_scan/user_action_required</code>。<code>service_login_failed</code>、<code>service_login_code_*</code> 可以作为 auth 域错误标签， 但未知非零 code（例如 <code>10001</code>、<code>500</code>）不得自动变成长期失效或扫码要求。</p><h3 id="_4-2-fatal-gate" tabindex="-1">4.2 Fatal gate <a class="header-anchor" href="#_4-2-fatal-gate" aria-label="Permalink to &quot;4.2 Fatal gate&quot;">​</a></h3><p>首次收到 fatal 分类即：</p><ul><li>state=<code>LOCKED</code></li><li>设置 <code>_last_manual_login_required_reason</code></li><li>设置 lock transition reason</li><li><code>is_auth_locked()</code> 持续为 true，直到显式清除或 verified recovery 成功</li><li>公共映射：<code>status_reason=manual_login_required</code></li></ul><p>非 force <code>ensure_auth()</code> 在任何 probe 前短路，不重复访问小米接口。</p><h3 id="_4-3-verified-recovery-clear" tabindex="-1">4.3 Verified recovery clear <a class="header-anchor" href="#_4-3-verified-recovery-clear" aria-label="Permalink to &quot;4.3 Verified recovery clear&quot;">​</a></h3><p>以下成功必须清除 manual gate：</p><ul><li>verified fast rebind</li><li>atomic persistent refresh</li><li>env runtime rebind</li><li>manual reload success</li><li>force ensure/_try_login success</li><li>full login 成功且 runtime verify 已完成</li></ul><p>清理内容：</p><ul><li>state=<code>HEALTHY</code></li><li><code>locked_until=0</code></li><li><code>_last_manual_login_required_reason=&quot;&quot;</code></li><li>lock transition reason 清空</li></ul><p>失败路径不得清理。</p><h2 id="_5-transition-lock-与-generation" tabindex="-1">5. Transition lock 与 generation <a class="header-anchor" href="#_5-transition-lock-与-generation" aria-label="Permalink to &quot;5. Transition lock 与 generation&quot;">​</a></h2><p>请求在等待 <code>_auth_transition_lock</code> 前捕获 generation。获得 lock 后：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果 generation 已变化</span></span>
<span class="line"><span>且 state=HEALTHY</span></span>
<span class="line"><span>且 runtime ready</span></span>
<span class="line"><span>=&gt; 复用先前成功事务并返回，不重复 recovery/login</span></span></code></pre></div><p>不得用 reason 字符串或 <code>lock.locked()</code> 的瞬时状态替代 generation 判断。</p><h2 id="_6-时间语义与观测" tabindex="-1">6. 时间语义与观测 <a class="header-anchor" href="#_6-时间语义与观测" aria-label="Permalink to &quot;6. 时间语义与观测&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间字段</th><th>语义</th><th>验收用途</th></tr></thead><tbody><tr><td>session success</td><td>会话建立/刷新成功</td><td>证明认证成功，不作 TTL</td></tr><tr><td>runtime verify</td><td>runtime 探针成功</td><td>证明当前 runtime 健康</td></tr><tr><td>refresh attempt</td><td>scheduled 尝试或 skip</td><td>证明节流边界</td></tr><tr><td><code>saveTime</code></td><td>持久 token 发行/刷新事实</td><td>唯一 TTL 锚点</td></tr></tbody></table><p>debug flow 必须保留：</p><ul><li><code>started_at</code> / <code>finished_at</code></li><li><code>primary_attempt</code></li><li><code>fallback_attempt</code></li><li><code>rebind</code></li><li><code>verify</code></li><li><code>result</code></li></ul><p>若 primary token exchange 成功但 candidate verify 失败：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>primary_attempt.result = ok</span></span>
<span class="line"><span>verify.result = failed</span></span></code></pre></div><h2 id="_7-验收规范" tabindex="-1">7. 验收规范 <a class="header-anchor" href="#_7-验收规范" aria-label="Permalink to &quot;7. 验收规范&quot;">​</a></h2><h3 id="_7-1-首次-scheduled-触发点" tabindex="-1">7.1 首次 scheduled 触发点 <a class="header-anchor" href="#_7-1-首次-scheduled-触发点" aria-label="Permalink to &quot;7.1 首次 scheduled 触发点&quot;">​</a></h3><p>构造：</p><ul><li>state=<code>HEALTHY</code></li><li>完整 persistent auth</li><li>持久 <code>saveTime</code> 进入 scheduled 阈值</li><li>可选旧 <code>serviceToken</code></li></ul><p>检查：</p><ol><li>只调用 atomic persistent-auth rebuild。</li><li><code>MiAccount.login</code> 未调用。</li><li>env override 时无换票、无 TokenStore.commit，trigger 为 <code>scheduled_env_override_skip</code>。</li><li>成功时 <code>saveTime</code> 由 TokenStore.commit 更新，runtime healthy。</li><li>失败时旧 <code>saveTime</code>、旧 runtime、state、<code>recovery_failure_count</code> 语义保持正确。</li><li><code>runtime verify</code> 时间不被用作 TTL。</li></ol><h3 id="_7-2-至少一个重复周期" tabindex="-1">7.2 至少一个重复周期 <a class="header-anchor" href="#_7-2-至少一个重复周期" aria-label="Permalink to &quot;7.2 至少一个重复周期&quot;">​</a></h3><p>在第一次 scheduled 成功、失败或 skip 后推进可控时间，至少再次执行一个周期：</p><ul><li>attempt cooldown 未到：不得再次换票/登录。</li><li>cooldown 到期：最多一次新的 atomic candidate 尝试。</li><li>不得因每次 keepalive probe 成功而重置 token TTL。</li><li>记录并检查 <code>last_refresh_attempt_ts</code>、<code>last_session_success_ts</code>、 <code>last_runtime_verify_ts</code> 的独立语义。</li></ul><h3 id="_7-3-natural-expiry" tabindex="-1">7.3 Natural expiry <a class="header-anchor" href="#_7-3-natural-expiry" aria-label="Permalink to &quot;7.3 Natural expiry&quot;">​</a></h3><p>即使旧 <code>serviceToken</code> 仍在磁盘：</p><ul><li>runtime probe auth failure 后必须进入 atomic rebuild。</li><li>atomic failure 不得进入无口令 <code>MiAccount.login</code>。</li><li>Reactive probe 或 manual reload 首次遇到 70016/87001 必须映射 <code>manual_login_required</code> 且 <code>long_term_expired=false</code>，第二次非 force ensure 不得再次调用 <code>_serviceLogin</code>。</li><li>Scheduled 遇到上述两类保持 <code>healthy</code>，记录 suspended 及原因，后续周期零网络；verified recovery 清除 suspended。网络/5xx/unknown 只走 attempt cooldown。</li><li>10001/500 等未知非零 code 不得误报扫码。</li></ul><h3 id="_7-4-manual-reload" tabindex="-1">7.4 Manual reload <a class="header-anchor" href="#_7-4-manual-reload" aria-label="Permalink to &quot;7.4 Manual reload&quot;">​</a></h3><ul><li>先断言真实调用 <code>TokenStore.reload_from_disk()</code>。</li><li>env 模式只 rebind/verify，不换票、不写盘。</li><li>fatal 失败检查：state、<code>auth_locked</code>、<code>need_qr_scan</code>、<code>manual_login_required_reason</code>、 <code>runtime_auth_ready=false</code>。</li><li>verified recovery 后检查 state=<code>HEALTHY</code>、<code>is_auth_locked=false</code>、reason 为空， 随后普通 <code>ensure_auth()</code> 可继续执行。</li></ul><h3 id="_7-5-failure-accounting" tabindex="-1">7.5 Failure accounting <a class="header-anchor" href="#_7-5-failure-accounting" aria-label="Permalink to &quot;7.5 Failure accounting&quot;">​</a></h3><p>验收必须检查：</p><ul><li><code>failure_count/recovery_failure_count</code></li><li><code>error_code</code></li><li><code>status_reason</code></li><li><code>TokenStore.saveTime</code></li><li><code>runtime_swap_attempted/runtime_swap_applied</code></li><li><code>MiAccount.login</code> 和 <code>_serviceLogin</code> 的调用证据</li></ul><h2 id="_8-观测接口" tabindex="-1">8. 观测接口 <a class="header-anchor" href="#_8-观测接口" aria-label="Permalink to &quot;8. 观测接口&quot;">​</a></h2><p>正式状态：</p><ul><li><code>/api/v1/auth/status</code></li></ul><p>调试状态：</p><ul><li><code>/api/v1/debug/auth_state</code></li><li><code>/api/v1/debug/auth_recovery_state</code></li><li><code>/api/v1/debug/auth_runtime_reload_state</code></li><li><code>/api/v1/debug/auth_short_session_rebuild_state</code></li></ul><p>调试接口必须能区分：</p><ul><li><code>manual_login_required</code></li><li><code>short_session_rebuild_failed</code></li><li><code>runtime_not_ready</code></li><li><code>scheduled_env_override_skip</code></li><li>primary exchange failure</li><li>candidate verify failure</li><li>token commit failure</li></ul>`,79)]))}const _=i(d,[["render",l]]);export{h as __pageData,_ as default};
